#![forbid(unsafe_code)]
use sv_claude_kaggle::{need,parse,R,LICENCIA};use std::{fs,path::Path};use serde_json::json;
fn read(root:&Path,p:&str)->R<String>{fs::read_to_string(root.join(p)).map_err(|e|e.to_string())}
fn sin_fila(s:&str,id:&str)->String{s.split_inclusive('\n').filter(|r|!r.starts_with(&format!("\"{id}\","))&&!r.contains(&format!(",\"{id}\","))).collect()}
fn run()->R<()>{let a:Vec<_>=std::env::args().collect();need(a.len()==5,"ORIGINALES PREPARADOS IDENTIDAD INFORME")?;let old=Path::new(&a[1]);let new=Path::new(&a[2]);let id=parse(&fs::read(&a[3]).map_err(|e|e.to_string())?)?;let rev=id["revision"].as_u64().ok_or("Revisión")?;let retp=id["registro"].as_str().ok_or("Registro")?;for(p,row)in[("docs/calidad/Inventario-sv/sucesos/SUCESOS_SV.csv","S39"),("docs/calidad/Inventario-sv/tiques-tecnicos/TIQUES_TECNICOS.csv","TT-0026")]{let x=read(old,p)?;let y=read(new,p)?;need(x!=y&&sin_fila(&x,row)==sin_fila(&y,row),"Filas ajenas modificadas")?;}for(p,prefix)in[("docs/calidad/Inventario-sv/sucesos/HISTORIAL_SUCESOS_SV.csv",format!("\"{rev}\",\"S39\",")),("docs/calidad/REGISTRO_EVOLUCION_TECNICA_PROYECTO.csv",format!("\"{retp}\","))]{let x=read(old,p)?;let y=read(new,p)?;need(y.starts_with(&x),"Historia reescrita")?;let tail=&y[x.len()..];need(tail.starts_with(&prefix)&&tail.lines().count()==1,"Incorporación ajena o múltiple")?;}for p in["docs/calidad/Inventario-sv/sucesos/SUCESOS_SV.md","docs/calidad/Inventario-sv/tiques-tecnicos/TT-0026.md","docs/calidad/tuberias-ia/continuacion-15-09-2026/ACTA_005_CLAUDE_OPUS_5_5_NODO02_2026_10_09.md","docs/calidad/REGISTRO_EVOLUCION_TECNICA_PROYECTO.md"]{let x=read(old,p)?;let y=read(new,p)?;need(y.starts_with(&x)&&y[x.len()..].contains("recepción científica independiente pendiente")&&y[x.len()..].contains("sesión Kaggle apagada")&&y[x.len()..].contains("23 generaciones nuevas")&&y[x.len()..].contains("8/9"),"Antecedente o alcance documental distintos")?;}let p="docs/calidad/Inventario-sv/tiques-tecnicos/json/TT-0026_CLAUDE_OPUS_5_5_NODO02_2026-10-09.json";let x=parse(read(old,p)?.as_bytes())?;let y=parse(read(new,p)?.as_bytes())?;need(x["cyb16"]==y["cyb16"]&&y["revision_suceso"]==rev&&y["cyb09"]["generaciones_nuevas"]==23&&y["cyb09"]["originales_reutilizados"]==4&&y["cyb09"]["resultado"]["correctas"]==8&&y["cyb09"]["resultado"]["admisible_segun_clave"]==false&&y["cyb09"]["recepcion_independiente"]=="pendiente","Tique o resultado discordantes")?;fs::write(&a[4],serde_json::to_vec_pretty(&json!({"conforme":true,"filas_ajenas_identicas":true,"historia_preservada":true,"documentos_antecedentes_preservados":true,"revision_S39":rev,"registro":retp,"generaciones_nuevas":23,"resultado_asistido_R2":"8/9; no admisible por C02 crítico","recepcion_independiente":"pendiente","licencia":LICENCIA})).unwrap()).map_err(|e|e.to_string())?;println!("Registros cotejados en Rust: antecedentes y filas ajenas conservados; resultado y retorno coherentes");Ok(())}
fn main(){if let Err(e)=run(){eprintln!("NO CONFORME: {e}");std::process::exit(1)}}
